use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary shell command string via `sh -c` and returns the full output.
pub fn run_command(cmd: &str) -> Result<Output, io::Error> {
    Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()
}

/// Executes a command and returns stdout as a trimmed String.
pub fn run_command_output(cmd: &str) -> Result<String, io::Error> {
    let output = run_command(cmd)?;
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    Ok(stdout)
}

/// Executes a command with explicit argv (no shell expansion).
pub fn run_command_argv(program: &str, args: &[&str]) -> Result<Output, io::Error> {
    Command::new(program)
        .args(args)
        .output()
}

